@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;
    private final EmailService emailService;

    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody OrderRequest request) {
        // Main request thread handles this
        var order = orderService.createOrder(request);

        // Spawn background thread for email notification
        CompletableFuture.runAsync(() -> {
            emailService.sendConfirmation(order.getCustomerEmail(), order);
        });

        // Return immediately without waiting for email
        return ResponseEntity.ok(order);
    }

    @GetMapping("/process-batch")
    public ResponseEntity<String> processBatch() {
        var orders = orderService.getPendingOrders();
        var executor = Executors.newFixedThreadPool(10);

        // Process 100 orders concurrently with 10 threads
        orders.forEach(order -> executor.submit(() -> {
            orderService.processPayment(order);
        }));

        executor.shutdown();
        return ResponseEntity.accepted().body("Processing started");
    }
}
