public class ThreadSafetyDemo {
    // Non-thread-safe counter
    static class UnsafeCounter {
        private int count = 0;

        public void increment() {
            count++; // This is NOT atomic: read, add, write
        }

        public int getCount() { return count; }
    }

    // Thread-safe counter using synchronized
    static class SafeCounter {
        private int count = 0;

        public synchronized void increment() {
            count++; // synchronized ensures atomicity
        }

        public synchronized int getCount() { return count; }
    }

    // Thread-safe using AtomicInteger
    static class AtomicCounter {
        private final AtomicInteger count = new AtomicInteger(0);

        public void increment() {
            count.incrementAndGet(); // Lock-free atomic operation
        }

        public int getCount() { return count.get(); }
    }
}
