public class ContextSwitchDemo {
    public static void main(String[] args) throws Exception {
        var cores = Runtime.getRuntime().availableProcessors();
        System.out.println("CPU cores: " + cores);

        // Test 1: Optimal thread count (matches cores)
        testWithThreads(cores, "Optimal");

        // Test 2: Excessive thread count (10x cores)
        testWithThreads(cores * 10, "Excessive");
    }

    static void testWithThreads(int threadCount, String label) throws Exception {
        var executor = Executors.newFixedThreadPool(threadCount);
        var start = System.currentTimeMillis();

        // Submit CPU-bound work
        var futures = new ArrayList<Future<Long>>();
        for (int i = 0; i < 100; i++) {
            futures.add(executor.submit(() -> {
                long sum = 0;
                for (int j = 0; j < 10_000_000; j++) {
                    sum += j; // CPU-intensive work
                }
                return sum;
            }));
        }

        for (var future : futures) future.get();
        var elapsed = System.currentTimeMillis() - start;
        System.out.println(label + " (" + threadCount + " threads): " + elapsed + "ms");
        executor.shutdown();
    }
}
